from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Lattice separators are solid, non-background-color lines. Blank zero
    # lines inside unfilled cells are not separators.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != 0]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != 0]
    row_bands, col_bands = [], []
    start = 0
    for r in sep_rows:
        if start < r: row_bands.append((start, r))
        start = r + 1
    if start < h: row_bands.append((start, h))
    start = 0
    for c in sep_cols:
        if start < c: col_bands.append((start, c))
        start = c + 1
    if start < w: col_bands.append((start, w))

    # Most frequent color inside the cells is their background.
    counts = Counter(grid[r][c] for r in range(h) if r not in sep_rows
                     for c in range(w) if c not in sep_cols)
    bg = counts.most_common(1)[0][0]
    tiles = []
    for r0, r1 in row_bands:
        for c0, c1 in col_bands:
            tile = [row[c0:c1] for row in grid[r0:r1]]
            if any(v != bg for row in tile for v in row):
                tiles.append((r0, r1, c0, c1, tile))
    out = [row[:] for row in grid]
    if not tiles:
        return out
    _, _, _, _, motif = tiles[0]
    for a, b in row_bands:
        for x, y in col_bands:
            if b-a == len(motif) and y-x == len(motif[0]):
                for dr in range(b-a):
                    out[a+dr][x:y] = motif[dr][:]
    return out

